import { Component, OnInit } from '@angular/core';
import { SaleService } from 'src/app/services/sale.service'; // adjust path if needed
import { Sale } from 'src/app/models/sale'; // adjust path if needed

@Component({
  selector: 'app-sales',
  templateUrl: './sales.component.html',
  styleUrls: ['./sales.component.css'],
})
export class SalesComponent implements OnInit {
  sales: Sale[] = []; // ✅ Declare the 'sales' array

  constructor(private saleService: SaleService) {}

  ngOnInit(): void {
    this.getAllSales();
  }

  getAllSales(): void {
    this.saleService.getSales().subscribe(
      (data: Sale[]) => {
        this.sales = data; // ✅ Assign fetched sales to the 'sales' property
      },
      (error) => {
        console.error('Error fetching sales', error);
      }
    );
  }
}
